export enum IssueType {
  AGGRESSIVE_BEHAVIOR = 'Aggressive Behavior',
  DOG_BITE = 'Dog Bite',
  SKIN_RASH = 'Skin Rash',
  SUSPECTED_RABIES = 'Suspected Rabies',
  INJURY = 'Injury',
  HEALTH_CONCERN = 'Health Concern',
  GENERAL = 'General Reporting'
}

export enum ReportStatus {
  PENDING = 'Pending',
  ACKNOWLEDGED = 'Acknowledged',
  IN_PROGRESS = 'In Progress',
  RESOLVED = 'Resolved'
}

export enum DogHealthStatus {
  STABLE = 'Stable',
  CRITICAL = 'Critical',
  UNDER_TREATMENT = 'Under Treatment',
  RECOVERED = 'Recovered',
  READY_FOR_ADOPTION = 'Ready for Adoption'
}

export interface Location {
  lat: number;
  lng: number;
  address?: string;
}

export interface Vaccination {
  name: string;
  date: string;
  nextDueDate: string;
}

export interface TreatmentRecord {
  date: string;
  diagnosis: string;
  treatment: string;
  notes: string;
}

export interface Dog {
  id: string;
  name?: string;
  breed: string;
  estimatedAge: string;
  gender: 'Male' | 'Female' | 'Unknown';
  healthStatus: DogHealthStatus;
  isSterilized: boolean;
  captureDate: string;
  captureLocation: Location;
  vaccinations: Vaccination[];
  treatmentHistory: TreatmentRecord[];
  photoUrl: string;
  isAdopted: boolean;
  adopter?: {
    name: string;
    phone: string;
    adoptionDate: string;
  };
}

export interface Report {
  id: string;
  type: IssueType;
  description: string;
  location: Location;
  status: ReportStatus;
  reporterName: string;
  timestamp: string;
  dogId?: string; // Linked if a dog record is created from this report
  resolutionAction?: string;
  expectedTimeline?: string;
}

