import { GoogleGenAI, Type } from "@google/genai";
import { IssueType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const analyzeReportSeverity = async (description: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze the following street dog issue report and categorize its severity (Low, Medium, High, Urgent) and suggest an action priority. 
      Report: "${description}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            severity: { type: Type.STRING },
            priority: { type: Type.STRING },
            reason: { type: Type.STRING }
          },
          required: ["severity", "priority", "reason"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini analysis failed", error);
    return null;
  }
};

export const generateAdoptableProfile = async (dogData: any) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a heartwarming 3-sentence adoption profile description for a street dog with the following details: 
      Name: ${dogData.name}, Breed: ${dogData.breed}, History: ${dogData.treatmentHistory?.[0]?.diagnosis || 'rescued from street'}.`,
    });
    return response.text;
  } catch (error) {
    return "A wonderful dog looking for a forever home.";
  }
};

import React from 'react';
import { UserRole } from '../types';
import { Dog, ClipboardList, ShieldCheck, Heart, LayoutDashboard } from 'lucide-react';

interface NavbarProps {
  role: UserRole;
  setRole: (role: UserRole) => void;
  activeTab: string;
  setActiveTab: (tab: string) => void;
}

const Navbar: React.FC<NavbarProps> = ({ role, setRole, activeTab, setActiveTab }) => {
  const tabs = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'reports', label: 'Issue Reports', icon: ClipboardList },
    { id: 'adoption', label: 'Adopt a Dog', icon: Heart },
    { id: 'records', label: 'Dog Records', icon: ShieldCheck, adminOnly: true },
  ];

  return (
    <nav className="bg-white border-b sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 items-center">
          <div className="flex items-center gap-2">
