import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Report, Dog, DogHealthStatus, ReportStatus } from '../types';
import { AlertTriangle, CheckCircle, Info, Activity } from 'lucide-react';

interface DashboardProps {
  reports: Report[];
  dogs: Dog[];
}

const Dashboard: React.FC<DashboardProps> = ({ reports, dogs }) => {
  const pendingCount = reports.filter(r => r.status === ReportStatus.PENDING).length;
  const inProgressCount = reports.filter(r => r.status === ReportStatus.IN_PROGRESS).length;
  const resolvedCount = reports.filter(r => r.status === ReportStatus.RESOLVED).length;

  const healthData = [
    { name: 'Healthy', value: dogs.filter(d => d.healthStatus === DogHealthStatus.READY_FOR_ADOPTION || d.healthStatus === DogHealthStatus.STABLE).length },
    { name: 'Under Treatment', value: dogs.filter(d => d.healthStatus === DogHealthStatus.UNDER_TREATMENT).length },
    { name: 'Critical', value: dogs.filter(d => d.healthStatus === DogHealthStatus.CRITICAL).length },
  ];

  const reportTypeData = Array.from(new Set(reports.map(r => r.type))).map(type => ({
    name: type,
    count: reports.filter(r => r.type === type).length
  }));

  const COLORS = ['#10b981', '#f59e0b', '#ef4444'];

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard title="Total Reports" value={reports.length} icon={<Info className="text-blue-600" />} />
        <StatCard title="Active Issues" value={pendingCount + inProgressCount} icon={<AlertTriangle className="text-amber-600" />} />
        <StatCard title="Resolved Cases" value={resolvedCount} icon={<CheckCircle className="text-emerald-600" />} />
        <StatCard title="Total Rescues" value={dogs.length} icon={<Activity className="text-purple-600" />} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-semibold mb-6 text-slate-800">Issues by Category</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={reportTypeData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis fontSize={12} tickLine={false} axisLine={false} />
                <Tooltip cursor={{ fill: '#f1f5f9' }} />
                <Bar dataKey="count" fill="#0d9488" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-semibold mb-6 text-slate-800">Rescue Health Distribution</h3>
          <div className="h-64 flex flex-col md:flex-row items-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={healthData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {healthData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="flex flex-col gap-2 mt-4 md:mt-0 md:ml-4">
              {healthData.map((entry, index) => (
                <div key={entry.name} className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }} />
                  <span className="text-sm text-slate-600">{entry.name}: {entry.value}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ title, value, icon }: { title: string, value: number, icon: React.ReactNode }) => (
  <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
    <div>
      <p className="text-sm text-slate-500 font-medium mb-1">{title}</p>
      <h4 className="text-2xl font-bold text-slate-900">{value}</h4>
    </div>
    <div className="bg-slate-50 p-3 rounded-lg">
      {icon}
    </div>
  </div>
);

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { IssueType, Report, ReportStatus, Location } from '../types';
import { MapPin, Send, Loader2, Info } from 'lucide-react';
import { analyzeReportSeverity } from '../services/gemini';

interface ReportFormProps {
  onReportSubmit: (report: Report) => void;
}

const ReportForm: React.FC<ReportFormProps> = ({ onReportSubmit }) => {
  const [description, setDescription] = useState('');
  const [type, setType] = useState<IssueType>(IssueType.GENERAL);
  const [reporterName, setReporterName] = useState('');
  const [location, setLocation] = useState<Location | null>(null);
  const [isLocating, setIsLocating] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiInsight, setAiInsight] = useState<{ severity: string, priority: string, reason: string } | null>(null);

  const handleLocate = () => {
    setIsLocating(true);
    if (!navigator.geolocation) {
      alert("Geolocation is not supported by your browser");
      setIsLocating(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude, address: 'Current Location Detected' });
        setIsLocating(false);
      },
      () => {
        alert("Unable to retrieve location");
        setIsLocating(false);
      }
    );
  };

  useEffect(() => {
    const delayDebounceFn = setTimeout(async () => {
      if (description.length > 20) {
        const insight = await analyzeReportSeverity(description);
        if (insight) setAiInsight(insight);
      } else {
        setAiInsight(null);
      }
    }, 1000);

    return () => clearTimeout(delayDebounceFn);
  }, [description]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!location) {
      alert("Please provide location");
      return;
    }

    setIsSubmitting(true);
    const newReport: Report = {
      id: `R-${Date.now()}`,
      type,
      description,
      location,
      status: ReportStatus.PENDING,
      reporterName,
      timestamp: new Date().toISOString()
    };

    setTimeout(() => {
      onReportSubmit(newReport);
      setDescription('');
      setReporterName('');
      setLocation(null);
      setIsSubmitting(false);
      setAiInsight(null);
    }, 800);
  };

  return (
    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm max-w-2xl mx-auto">
      <div className="flex items-center gap-2 mb-6 text-teal-700">
        <div className="p-2 bg-teal-50 rounded-lg">
          <Info className="h-5 w-5" />
        </div>
        <h2 className="text-xl font-bold">Report an Issue</h2>
      </div>

      <form onSubmit={handleSubmit} className="space-y-5">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Your Name</label>
            <input
              type="text"
              required
              value={reporterName}
              onChange={(e) => setReporterName(e.target.value)}
              className="w-full rounded-lg border-slate-300 focus:border-teal-500 focus:ring-teal-500 transition-all text-sm"
              placeholder="Full name"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Issue Type</label>
            <select
              value={type}
              onChange={(e) => setType(e.target.value as IssueType)}
              className="w-full rounded-lg border-slate-300 focus:border-teal-500 focus:ring-teal-500 transition-all text-sm"
            >
              {Object.values(IssueType).map((val) => (
                <option key={val} value={val}>{val}</option>
              ))}
            </select>
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">Detailed Description</label>
          <textarea
            required
            rows={4}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className="w-full rounded-lg border-slate-300 focus:border-teal-500 focus:ring-teal-500 transition-all text-sm"
            placeholder="Describe the dog's behavior, health, or specific incident..."
          />
          {aiInsight && (
            <div className="mt-2 p-3 bg-amber-50 border border-amber-200 rounded-lg text-xs flex items-start gap-2 animate-pulse">
              <div className="p-1 bg-amber-100 rounded text-amber-700 font-bold uppercase shrink-0">AI Insight</div>
              <div>
                <span className="font-semibold text-amber-800">Severity: {aiInsight.severity} ({aiInsight.priority})</span>
                <p className="text-amber-700 mt-1">{aiInsight.reason}</p>
              </div>
            </div>
          )}
        </div>

        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={handleLocate}
            disabled={isLocating}
            className={`flex-1 flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg border border-slate-300 hover:bg-slate-50 transition-colors text-sm font-medium ${location ? 'border-teal-500 bg-teal-50 text-teal-700' : 'text-slate-700'}`}
          >
            {isLocating ? <Loader2 className="h-4 w-4 animate-spin" /> : <MapPin className="h-4 w-4" />}
            {location ? 'Location Updated' : 'Capture My Location'}
          </button>
        </div>

        <button
          type="submit"
          disabled={isSubmitting}
          className="w-full flex items-center justify-center gap-2 px-6 py-3 bg-teal-600 hover:bg-teal-700 text-white rounded-lg font-bold shadow-sm transition-all disabled:opacity-50"
        >
          {isSubmitting ? <Loader2 className="h-5 w-5 animate-spin" /> : <Send className="h-5 w-5" />}
          Submit Report
        </button>
      </form>
    </div>
  );
};

export default ReportForm;

import React, { useState } from 'react';
import { Dog, DogHealthStatus } from '../types';
import { Heart, User, Phone, CheckCircle2, ChevronRight, Activity, Calendar } from 'lucide-react';

interface AdoptionModuleProps {
  dogs: Dog[];
  onAdopt: (dogId: string, adopter: { name: string; phone: string }) => void;
}

const AdoptionModule: React.FC<AdoptionModuleProps> = ({ dogs, onAdopt }) => {
  const [selectedDog, setSelectedDog] = useState<Dog | null>(null);
  const [adopterName, setAdopterName] = useState('');
  const [adopterPhone, setAdopterPhone] = useState('');
  const [success, setSuccess] = useState(false);

  const adoptableDogs = dogs.filter(d => d.healthStatus === DogHealthStatus.READY_FOR_ADOPTION && !d.isAdopted);

  const handleAdoption = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDog) return;

    onAdopt(selectedDog.id, { name: adopterName, phone: adopterPhone });
    setSuccess(true);
    setTimeout(() => {
      setSuccess(false);
      setSelectedDog(null);
      setAdopterName('');
      setAdopterPhone('');
    }, 3000);
  };

  if (selectedDog) {
    return (
      <div className="max-w-4xl mx-auto space-y-6 animate-in fade-in duration-300">
        <button onClick={() => setSelectedDog(null)} className="text-teal-600 font-medium hover:underline flex items-center gap-1">
          &larr; Back to Listings
        </button>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 bg-white p-8 rounded-2xl border border-slate-200 shadow-lg">
          <div className="space-y-4">
            <img src={selectedDog.photoUrl} alt={selectedDog.name} className="w-full h-80 object-cover rounded-xl shadow-inner" />
            <div className="flex gap-2 flex-wrap">
              <span className="px-3 py-1 bg-teal-100 text-teal-800 rounded-full text-xs font-bold uppercase">{selectedDog.breed}</span>
              <span className="px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-xs font-bold uppercase">{selectedDog.gender}</span>
              <span className="px-3 py-1 bg-amber-100 text-amber-800 rounded-full text-xs font-bold uppercase">{selectedDog.estimatedAge}</span>
            </div>
          </div>

          <div className="space-y-6">
            <div>
              <h2 className="text-3xl font-bold text-slate-800">{selectedDog.name || 'Friendly Indie'}</h2>
              <p className="text-slate-500 mt-2">Ready for a forever home. All medical records will be transferred to you upon adoption.</p>
            </div>

            <div className="bg-slate-50 p-4 rounded-xl space-y-3">
              <h3 className="font-semibold text-slate-700 flex items-center gap-2">
                <Activity className="h-4 w-4" /> Health Status
              </h3>
              <div className="text-sm text-slate-600">
                <p>• Fully Vaccinated: {selectedDog.vaccinations.length > 0 ? 'Yes' : 'Pending'}</p>
                <p>• Sterilized: {selectedDog.isSterilized ? 'Yes' : 'No'}</p>
                <p>• Latest Checkup: {selectedDog.treatmentHistory[0]?.date || 'N/A'}</p>
              </div>
            </div>

            {!success ? (
              <form onSubmit={handleAdoption} className="space-y-4 pt-4 border-t border-slate-100">
                <h4 className="font-bold text-slate-800">Registration Details</h4>
                <div className="space-y-3">
                  <div className="relative">
                    <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 h-4 w-4" />
                    <input
                      required
                      type="text"
                      placeholder="Your Full Name"
                      value={adopterName}
                      onChange={(e) => setAdopterName(e.target.value)}
                      className="w-full pl-10 rounded-lg border-slate-200 focus:ring-teal-500 focus:border-teal-500"
                    />
                  </div>
                  <div className="relative">
                    <Phone className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 h-4 w-4" />
                    <input
                      required
                      type="tel"
                      placeholder="Mobile Number"
                      value={adopterPhone}
                      onChange={(e) => setAdopterPhone(e.target.value)}
                      className="w-full pl-10 rounded-lg border-slate-200 focus:ring-teal-500 focus:border-teal-500"
                    />
                  </div>
                </div>
                <button
                  type="submit"
                  className="w-full py-4 bg-teal-600 hover:bg-teal-700 text-white rounded-xl font-bold transition-all flex items-center justify-center gap-2"
                >
                  <Heart className="fill-current" />
                  Request Adoption
                </button>
              </form>
            ) : (
              <div className="text-center p-8 bg-emerald-50 border border-emerald-200 rounded-xl space-y-4">
                <div className="mx-auto w-16 h-16 bg-emerald-500 text-white rounded-full flex items-center justify-center">
                  <CheckCircle2 className="h-8 w-8" />
                </div>
                <h3 className="text-xl font-bold text-emerald-900">Application Submitted!</h3>
                <p className="text-emerald-700">Thank you for giving {selectedDog.name} a chance. Our team will contact you shortly.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <div className="text-center space-y-2">
        <h2 className="text-4xl font-extrabold text-slate-900 tracking-tight">Meet Your Future Best Friend</h2>
        <p className="text-slate-500 max-w-2xl mx-auto">These brave rescues have been treated, vaccinated, and are waiting for a loving home.</p>
      </div>

      {adoptableDogs.length === 0 ? (
