import React, { useState } from 'react';
import { Report, Dog, ReportStatus, DogHealthStatus, IssueType } from '../types';
import { CheckCircle, Clock, Trash2, Edit3, Plus, ChevronDown, ChevronUp, MapPin } from 'lucide-react';

interface AdminPanelProps {
  reports: Report[];
  dogs: Dog[];
  onUpdateReport: (reportId: string, updates: Partial<Report>) => void;
  onAddDog: (dog: Dog) => void;
  onUpdateDog: (dogId: string, updates: Partial<Dog>) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ reports, dogs, onUpdateReport, onAddDog, onUpdateDog }) => {
  const [expandedReport, setExpandedReport] = useState<string | null>(null);
  const [resolutionText, setResolutionText] = useState('');

  const handleAcknowledge = (report: Report) => {
    onUpdateReport(report.id, { 
      status: ReportStatus.ACKNOWLEDGED,
      expectedTimeline: '24-48 Hours'
    });
  };

  const handleResolve = (report: Report) => {
    if (!resolutionText) {
      alert("Please provide resolution action details");
      return;
    }

    // Automatically create a dog record if needed
    if (!report.dogId && report.type !== IssueType.GENERAL) {
      const newDog: Dog = {
        id: `D-${Date.now()}`,
        breed: 'Unknown/Mixed',
        estimatedAge: 'Unknown',
        gender: 'Unknown',
        healthStatus: DogHealthStatus.UNDER_TREATMENT,
        isSterilized: false,
        captureDate: new Date().toISOString().split('T')[0],
        captureLocation: report.location,
        vaccinations: [],
        treatmentHistory: [{
          date: new Date().toISOString().split('T')[0],
          diagnosis: report.type,
          treatment: resolutionText,
          notes: 'Case captured from citizen report'
        }],
        photoUrl: `https://picsum.photos/seed/${Date.now()}/400/300`,
        isAdopted: false
      };
      onAddDog(newDog);
      onUpdateReport(report.id, { status: ReportStatus.RESOLVED, resolutionAction: resolutionText, dogId: newDog.id });
    } else {
      onUpdateReport(report.id, { status: ReportStatus.RESOLVED, resolutionAction: resolutionText });
    }

    setResolutionText('');
    setExpandedReport(null);
  };

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-800">Operational Queue</h2>
        <div className="flex gap-2">
          <span className="px-3 py-1 bg-amber-100 text-amber-700 text-xs font-bold rounded-full">
            {reports.filter(r => r.status === ReportStatus.PENDING).length} New
          </span>
          <span className="px-3 py-1 bg-blue-100 text-blue-700 text-xs font-bold rounded-full">
            {reports.filter(r => r.status === ReportStatus.IN_PROGRESS).length} Active
          </span>
        </div>
      </div>

      <div className="space-y-4">
        {reports.map((report) => (
          <div key={report.id} className={`bg-white rounded-xl border transition-all ${expandedReport === report.id ? 'ring-2 ring-teal-500 border-teal-500 shadow-md' : 'border-slate-200 shadow-sm'}`}>
            <div 
              className="p-5 flex items-center justify-between cursor-pointer"
              onClick={() => setExpandedReport(expandedReport === report.id ? null : report.id)}
            >
              <div className="flex items-center gap-4">
                <div className={`p-2 rounded-lg ${
                  report.status === ReportStatus.PENDING ? 'bg-amber-100 text-amber-600' :
                  report.status === ReportStatus.RESOLVED ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'
                }`}>
                  {report.status === ReportStatus.PENDING ? <Clock className="h-5 w-5" /> : <CheckCircle className="h-5 w-5" />}
                </div>
                <div>
                  <h4 className="font-bold text-slate-800">{report.type}</h4>
                  <p className="text-xs text-slate-500 flex items-center gap-1">
                    <MapPin className="h-3 w-3" /> {report.location.address} • {new Date(report.timestamp).toLocaleDateString()}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <span className={`text-xs font-bold uppercase px-2 py-1 rounded ${
                  report.status === ReportStatus.PENDING ? 'bg-amber-50 text-amber-600' :
                  report.status === ReportStatus.RESOLVED ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'
                }`}>
                  {report.status}
                </span>
                {expandedReport === report.id ? <ChevronUp /> : <ChevronDown />}
              </div>
            </div>

            {expandedReport === report.id && (
              <div className="px-5 pb-5 pt-2 border-t border-slate-50 space-y-4">
                <div className="bg-slate-50 p-4 rounded-lg">
                  <p className="text-sm text-slate-700 leading-relaxed italic">"{report.description}"</p>
                  <p className="text-xs text-slate-400 mt-2">Reported by: {report.reporterName}</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {report.status === ReportStatus.PENDING && (
                    <button
                      onClick={() => handleAcknowledge(report)}
                      className="flex items-center justify-center gap-2 py-2.5 px-4 bg-teal-600 text-white rounded-lg font-semibold hover:bg-teal-700 transition-colors"
                    >
                      <CheckCircle className="h-4 w-4" /> Acknowledge Case
                    </button>
                  )}

                  {report.status !== ReportStatus.RESOLVED && (
                    <div className="col-span-full space-y-3">
                      <label className="text-sm font-semibold text-slate-700">Resolution Action</label>
                      <textarea
                        value={resolutionText}
                        onChange={(e) => setResolutionText(e.target.value)}
                        placeholder="Detail the action taken (e.g., Dog captured for vaccination and sterilization)..."
                        className="w-full text-sm rounded-lg border-slate-300 focus:ring-teal-500"
                        rows={3}
                      />
                      <button
                        onClick={() => handleResolve(report)}
                        className="w-full py-2.5 bg-emerald-600 text-white rounded-lg font-bold hover:bg-emerald-700 transition-colors"
                      >
                        Complete & Close Case
                      </button>
                    </div>
                  )}
                </div>

                {report.status === ReportStatus.RESOLVED && (
                  <div className="p-4 bg-emerald-50 rounded-lg text-emerald-800 text-sm">
                    <strong>Action Taken:</strong> {report.resolutionAction}
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>

      <div className="mt-12 border-t border-slate-200 pt-8">
        <h2 className="text-2xl font-bold text-slate-800 mb-6">Rescue Management</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {dogs.map((dog) => (
            <div key={dog.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col">
              <div className="flex items-center gap-4 mb-4">
                <img src={dog.photoUrl} alt={dog.id} className="w-16 h-16 rounded-lg object-cover" />
                <div>
                  <h4 className="font-bold text-slate-800">{dog.name || dog.id}</h4>
                  <span className="text-xs text-slate-500">{dog.breed} • {dog.healthStatus}</span>
                </div>
              </div>
              <div className="flex-1 space-y-2 mb-4">
                <div className="text-xs text-slate-600 flex justify-between">
                  <span>Vaccinations:</span>
                  <span className="font-bold">{dog.vaccinations.length}</span>
                </div>
                <div className="text-xs text-slate-600 flex justify-between">
                  <span>Adoption Status:</span>
                  <span className={`font-bold ${dog.isAdopted ? 'text-emerald-600' : 'text-amber-600'}`}>
                    {dog.isAdopted ? 'Adopted' : 'Searching'}
                  </span>
                </div>
              </div>
              <button className="w-full py-2 border border-slate-200 rounded-lg text-xs font-bold hover:bg-slate-50 flex items-center justify-center gap-2">
                <Edit3 className="h-3 w-3" /> Update Record
              </button>
            </div>
          ))}
          <div className="border-2 border-dashed border-slate-200 rounded-xl p-6 flex flex-col items-center justify-center text-slate-400 hover:border-teal-400 hover:text-teal-400 cursor-pointer transition-colors">
            <Plus className="h-8 w-8 mb-2" />
            <span className="font-bold">Manual Rescue Entry</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
