          <button onClick={() => setNotifications([])} className="text-slate-400 hover:text-white ml-2">×</button>
        </div>
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { IssueType } from "../types";

// Always use the process.env.API_KEY directly for initialization without fallbacks
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeReportSeverity = async (description: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze the following street dog issue report and categorize its severity (Low, Medium, High, Urgent) and suggest an action priority. 
      Report: "${description}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            severity: { type: Type.STRING },
            priority: { type: Type.STRING },
            reason: { type: Type.STRING }
          },
          required: ["severity", "priority", "reason"]
        }
      }
    });
    // Accessing .text property directly as per latest SDK guidelines
    const text = response.text;
    if (!text) return null;
    return JSON.parse(text);
  } catch (error) {
    console.error("Gemini analysis failed", error);
    return null;
  }
};

export const generateAdoptableProfile = async (dogData: any) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a heartwarming 3-sentence adoption profile description for a street dog with the following details: 
      Name: ${dogData.name}, Breed: ${dogData.breed}, History: ${dogData.treatmentHistory?.[0]?.diagnosis || 'rescued from street'}.`,
    });
    // Accessing .text property directly as per latest SDK guidelines
    return response.text || "A wonderful dog looking for a forever home.";
  } catch (error) {
    return "A wonderful dog looking for a forever home.";
  }
};

import React, { useState } from 'react';
import { Dog, DogHealthStatus } from '../types';
// Aliasing Dog icon to DogIcon to avoid conflict with the Dog interface/type
import { Heart, User, Phone, CheckCircle2, ChevronRight, Activity, Calendar, Dog as DogIcon } from 'lucide-react';

interface AdoptionModuleProps {
  dogs: Dog[];
  onAdopt: (dogId: string, adopter: { name: string; phone: string }) => void;
}

const AdoptionModule: React.FC<AdoptionModuleProps> = ({ dogs, onAdopt }) => {
  const [selectedDog, setSelectedDog] = useState<Dog | null>(null);
  const [adopterName, setAdopterName] = useState('');
