import React, { useState, useEffect } from 'react';
import { UserRole, Report, Dog } from './types';
import { MOCK_REPORTS, MOCK_DOGS } from './constants';
import Navbar from './components/Navbar';
import Dashboard from './components/Dashboard';
import ReportForm from './components/ReportForm';
import AdminPanel from './components/AdminPanel';
import AdoptionModule from './components/AdoptionModule';
import TechnicalDocs from './components/TechnicalDocs';
import { Bell, Heart } from 'lucide-react';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>('CITIZEN');
  const [activeTab, setActiveTab] = useState<string>('dashboard');
  const [reports, setReports] = useState<Report[]>(MOCK_REPORTS);
  const [dogs, setDogs] = useState<Dog[]>(MOCK_DOGS);
  const [notifications, setNotifications] = useState<string[]>([]);

  const handleNewReport = (report: Report) => {
    setReports([report, ...reports]);
    setNotifications([`New report submitted: ${report.type}`, ...notifications]);
    setActiveTab('reports');
  };

  const handleUpdateReport = (id: string, updates: Partial<Report>) => {
    setReports(reports.map(r => r.id === id ? { ...r, ...updates } : r));
    setNotifications([`Case updated: ${id} is now ${updates.status}`, ...notifications]);
  };

  const handleAddDog = (dog: Dog) => {
    setDogs([dog, ...dogs]);
  };

  const handleUpdateDog = (id: string, updates: Partial<Dog>) => {
    setDogs(dogs.map(d => d.id === id ? { ...d, ...updates } : d));
  };

  const handleAdoption = (dogId: string, adopter: { name: string; phone: string }) => {
    setDogs(dogs.map(d => d.id === dogId ? { 
      ...d, 
      isAdopted: true, 
      adopter: { ...adopter, adoptionDate: new Date().toISOString().split('T')[0] } 
    } : d));
    setNotifications([`Adoption request approved for ${adopter.name}!`, ...notifications]);
  };

  return (
    <div className="min-h-screen flex flex-col pb-12">
      <Navbar role={role} setRole={setRole} activeTab={activeTab} setActiveTab={setActiveTab} />

      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {/* Dynamic Header */}
        <div className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold text-slate-900">
              {activeTab === 'dashboard' && 'Community Overview'}
              {activeTab === 'reports' && 'Street Dog Reporting'}
              {activeTab === 'adoption' && 'Adoption Center'}
              {activeTab === 'records' && 'Medical Registry'}
              {activeTab === 'docs' && 'Technical Overview'}
            </h1>
            <p className="text-slate-500 mt-1">
              {activeTab === 'dashboard' && 'Monitoring local canine population health and safety.'}
              {activeTab === 'reports' && (role === 'ADMIN' ? 'Manage active complaints and welfare tasks.' : 'Help us help them. Report any concerns in your area.')}
              {activeTab === 'adoption' && 'Every street dog deserves a warm home and a loving family.'}
              {activeTab === 'records' && 'Secure digital management of rescue history and vaccinations.'}
              {activeTab === 'docs' && 'Detailed system architecture and model justifications.'}
            </p>
          </div>

          <div className="flex items-center gap-3">
            {notifications.length > 0 && (
              <div className="relative">
                <button className="p-2 bg-white border border-slate-200 rounded-full shadow-sm hover:bg-slate-50 transition-colors">
                  <Bell className="h-5 w-5 text-slate-600" />
                  <span className="absolute top-0 right-0 h-3 w-3 bg-red-500 rounded-full border-2 border-white"></span>
                </button>
              </div>
            )}
            <div className="px-4 py-2 bg-teal-600 text-white rounded-full text-sm font-bold shadow-sm flex items-center gap-2">
              <Heart className="h-4 w-4 fill-current" />
              Impact: {dogs.length} Rescues
