          {activeTab === 'dashboard' && <Dashboard reports={reports} dogs={dogs} />}

          {activeTab === 'reports' && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
              <div className="lg:col-span-5">
                <ReportForm onReportSubmit={handleNewReport} />
              </div>
              <div className="lg:col-span-7 space-y-4">
                <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center justify-between">
                  Your Recent Activity
                  <span className="text-xs font-normal text-slate-500">Auto-refreshing...</span>
                </h3>
                {reports.slice(0, 4).map((report) => (
                  <div key={report.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex justify-between items-center group hover:border-teal-300 transition-colors">
                    <div className="flex items-center gap-4">
                      <div className={`w-2 h-10 rounded-full ${
                        report.status === 'Resolved' ? 'bg-emerald-400' :
                        report.status === 'Acknowledged' ? 'bg-blue-400' : 'bg-amber-400'
                      }`} />
                      <div>
                        <h4 className="font-bold text-slate-800 text-sm">{report.type}</h4>
                        <p className="text-xs text-slate-500 line-clamp-1">{report.description}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded ${
                        report.status === 'Resolved' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600'
                      }`}>
                        {report.status}
                      </span>
                      <p className="text-[10px] text-slate-400 mt-1">Ref: {report.id}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'adoption' && <AdoptionModule dogs={dogs} onAdopt={handleAdoption} />}

          {activeTab === 'records' && role === 'ADMIN' && (
            <AdminPanel 
              reports={reports} 
              dogs={dogs} 
              onUpdateReport={handleUpdateReport} 
              onAddDog={handleAddDog} 
              onUpdateDog={handleUpdateDog} 
            />
          )}

          {activeTab === 'docs' && <TechnicalDocs />}
        </div>
      </main>

      {/* Persistent CTA for Citizen on small screens */}
      {role === 'CITIZEN' && activeTab !== 'reports' && activeTab !== 'docs' && (
        <div className="md:hidden fixed bottom-6 right-6 z-40">
          <button 
            onClick={() => setActiveTab('reports')}
            className="flex items-center justify-center gap-2 p-4 bg-teal-600 text-white rounded-full shadow-2xl hover:bg-teal-700 transition-all font-bold"
          >
            <Bell className="h-6 w-6" />
            Report Now
          </button>
        </div>
      )}

      {/* Notification Toast (Simplified) */}
      {notifications.length > 0 && (
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 bg-slate-900 text-white px-6 py-3 rounded-full shadow-xl flex items-center gap-3 animate-bounce">
          <div className="w-2 h-2 bg-teal-400 rounded-full" />
          <span className="text-sm font-medium">{notifications[0]}</span>
          <button onClick={() => setNotifications([])} className="text-slate-400 hover:text-white ml-2">×</button>
        </div>
      )}
    </div>
  );
};

export default App;

